#ifndef PLAYER_DATA_H
#define PLAYER_DATA_H

#include <genesis.h>

// Generated by tools/convert_players.py from player_list_v3_1_1.dat.
#define PLAYER_COUNT 4
#define PLAYER_WEAPON_N 12

#define PL_SHIELD  1
#define PL_SLIDE   2
#define PL_CHARGE  4
#define PL_DJUMP   8
#define PL_AIRDASH 16
#define PL_DIAG    32

typedef struct {
    const char *name;
    s8 wcol[PLAYER_WEAPON_N][3][3]; // per weapon: {c1, c2, c3}; -1 = unset
    u8 max_shots, simultaneous;
    s8 dmg_mod;
    u8 flags;                 // PL_* bits
    s8 full_id;               // full-charged projectile (-1 = default 10)
    s8 normal_id;             // normal projectile (-1 = default 0)
} PlayerData;

extern const PlayerData player_data[PLAYER_COUNT];

#endif
